const state = { products: [...seedProducts], stores: [], user: null, store: null, cart: readStore("yerli_cart", []), favorites: readStore("yerli_favorites", []), query: "", category: "Hamısı", location: "all", type: "all", color: "all", size: "all", minPrice: "", maxPrice: "", sort: "newest" };
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const productsGrid = $("#products-grid");
const resultCount = $("#result-count");
const emptyState = $("#empty-state");
const modalBackdrop = $("#modal-backdrop");
const toast = $("#toast");
let toastTimer; let sellerStep = 1; let sellerDraft = {}; let authStep = 1; let authIdentifier = ""; let afterAuth = null;

function readStore(key, fallback) { try { return JSON.parse(sessionStorage.getItem(key)) ?? fallback; } catch { return fallback; } }
function writeStore(key, value) { sessionStorage.setItem(key, JSON.stringify(value)); }
function money(value) { return `${Number(value).toFixed(0)} AZN`; }
function escapeHtml(value = "") { return String(value).replace(/[&<>'"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[c]); }
function mediaUrl(value) { if (!value) return imageUrls.shirt; if (/^(https?:|data:|blob:)/.test(value)) return value; return `${API_BASE}${value}`; }
function showToast(message) { clearTimeout(toastTimer); toast.textContent = message; toast.classList.add("show"); toastTimer = setTimeout(() => toast.classList.remove("show"), 3200); }
async function api(path, options = {}) { const headers = { "Content-Type": "application/json", ...(options.headers || {}) }; const token = sessionStorage.getItem("yerli_token"); if (token) headers.Authorization = `Bearer ${token}`; let response; try { response = await fetch(`${API_BASE}${path}`, { ...options, headers }); } catch { throw new Error("Serverə qoşulmaq mümkün olmadı. Backend serverini işə sal."); } const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.error || "Sorğu uğursuz oldu"); return payload; }
function productImage(product) { return mediaUrl(product.aiProcessed || product.processedUrl || product.image || product.images?.[0]?.ai_processed_url || product.images?.[0]?.original_url); }
function productFallback(product) { return product.category === "Ayaqqabı" ? "assets/product-shoes.svg" : product.category === "Çanta" ? "assets/product-bag.svg" : product.category === "Ev & həyat" ? "assets/product-home.svg" : product.category === "Aksesuar" ? "assets/product-watch.svg" : "assets/product-shirt.svg"; }
function bindProductImageFallbacks() { $$('img[data-image-fallback]').forEach(image => image.addEventListener("error", () => { if (image.dataset.fallbackUsed) return; image.dataset.fallbackUsed = "true"; image.src = image.dataset.imageFallback; })); }
function productText(product) { return `${product.title} ${product.category} ${product.subtype || ""} ${product.material || ""} ${product.store} ${product.city}`.toLocaleLowerCase("az"); }
function getVisibleProducts() { const tokens = state.query.toLocaleLowerCase("az").split(/\s+/).filter(Boolean); return state.products.filter(product => { const queryMatch = !tokens.length || tokens.every(token => productText(product).includes(token)); const categoryMatch = state.category === "Hamısı" || product.category === state.category; const typeMatch = state.type === "all" || product.category === state.type; const cityMatch = state.location === "all" || product.city === state.location; const colorMatch = state.color === "all" || product.colors?.includes(state.color); const sizeMatch = state.size === "all" || product.sizes?.includes(state.size); const minMatch = !state.minPrice || Number(product.price) >= Number(state.minPrice); const maxMatch = !state.maxPrice || Number(product.price) <= Number(state.maxPrice); return queryMatch && categoryMatch && typeMatch && cityMatch && colorMatch && sizeMatch && minMatch && maxMatch; }).sort((a, b) => state.sort === "low" ? a.price - b.price : state.sort === "high" ? b.price - a.price : 0); }
function renderProducts() { const items = getVisibleProducts(); resultCount.textContent = `${items.length} məhsul`; emptyState.hidden = items.length > 0; productsGrid.innerHTML = items.map(product => `<article class="product-card" data-product-id="${escapeHtml(product.id)}" tabindex="0"><div class="product-image-wrap"><img src="${escapeHtml(productImage(product))}" data-image-fallback="${productFallback(product)}" alt="${escapeHtml(product.title)}" loading="lazy" />${product.badge ? `<span class="product-badge">${escapeHtml(product.badge)}</span>` : ""}<button class="fav-btn ${state.favorites.includes(product.id) ? "faved" : ""}" data-favorite="${escapeHtml(product.id)}" aria-label="Seçilmişlərə əlavə et">${state.favorites.includes(product.id) ? "♥" : "♡"}</button><button class="add-card-btn" data-add="${escapeHtml(product.id)}" aria-label="Səbətə əlavə et">＋</button></div><div class="product-info"><div class="product-title">${escapeHtml(product.title)}</div><div class="product-store">${escapeHtml(product.store)}</div><div class="product-bottom"><strong class="product-price">${money(product.price)}</strong><span class="product-city">${escapeHtml(product.city)}</span></div></div></article>`).join(""); bindProductImageFallbacks(); renderActiveFilters(); }
function renderStores() { const container = $("#stores-grid"); if (!container) return; const directory = new Map(); state.stores.forEach(store => directory.set(store.name, { name: store.name, city: store.city, description: store.description, count: 0 })); state.products.forEach(product => { const existing = directory.get(product.store) || { name: product.store, city: product.city, description: "Yerli mağazadan seçilmiş məhsullar.", count: 0 }; existing.count += 1; existing.city = existing.city || product.city; directory.set(product.store, existing); }); const stores = [...directory.values()].sort((a, b) => b.count - a.count); container.innerHTML = stores.map(store => { const initials = store.name.split(/\\s+/).map(part => part[0]).join("").slice(0, 2).toUpperCase(); return `<button class="store-card" type="button" data-store-name="${escapeHtml(store.name)}"><span class="store-card-mark">${escapeHtml(initials)}</span><span class="store-card-copy"><strong>${escapeHtml(store.name)}</strong><small>${escapeHtml(store.city || "Azərbaycan")} · ${store.count} məhsul</small></span><span class="store-card-arrow">→</span></button>`; }).join(""); }
function renderActiveFilters() { const filters = []; if (state.query) filters.push([`Axtarış: ${state.query}`, () => { state.query = ""; $("#search-input").value = ""; }]); if (state.category !== "Hamısı") filters.push([state.category, () => { state.category = "Hamısı"; setCategoryPills(); }]); if (state.location !== "all") filters.push([state.location, () => { state.location = "all"; $("#location-filter").value = "all"; }]); if (state.type !== "all") filters.push([state.type, () => { state.type = "all"; $("#type-filter").value = "all"; }]); if (state.color !== "all") filters.push([state.color, () => { state.color = "all"; $("#color-filter").value = "all"; }]); if (state.size !== "all") filters.push([state.size, () => { state.size = "all"; $("#size-filter").value = "all"; }]); const container = $("#active-filters"); container.innerHTML = filters.map(([label], index) => `<span class="filter-tag">${escapeHtml(label)} <button data-remove-filter="${index}" aria-label="Filtri sil">×</button></span>`).join(""); container._filterActions = filters.map(item => item[1]); }
function setCategoryPills() { $$(".cat-pill").forEach(button => button.classList.toggle("active", button.dataset.category === state.category)); }
function clearFilters() { Object.assign(state, { query: "", category: "Hamısı", location: "all", type: "all", color: "all", size: "all", minPrice: "", maxPrice: "" }); $("#search-input").value = ""; ["location-filter", "type-filter", "color-filter", "size-filter"].forEach(id => { $("#" + id).value = "all"; }); $("#min-price").value = ""; $("#max-price").value = ""; setCategoryPills(); renderProducts(); }
function openModal(id) { modalBackdrop.hidden = false; $(id).hidden = false; document.body.classList.add("modal-open"); }
function closeAllLayers() { modalBackdrop.hidden = true; $$(".modal, .drawer").forEach(layer => { layer.hidden = true; }); document.body.classList.remove("modal-open"); }
function openCart() { renderCart(); modalBackdrop.hidden = false; $("#cart-drawer").hidden = false; document.body.classList.add("modal-open"); }
function updateAuthButton() { const button = $("#open-auth"); if (!button) return; button.textContent = state.user ? (state.store ? `Mağazam · ${state.store.name}` : `Hesab · ${state.user.identifier}`) : "Daxil ol"; button.classList.toggle("signed-in", !!state.user); }
function toggleFavorite(id) { state.favorites = state.favorites.includes(id) ? state.favorites.filter(item => item !== id) : [...state.favorites, id]; writeStore("yerli_favorites", state.favorites); renderProducts(); }
function addToCart(product, options = {}) { if (!Number.isInteger(Number(product.stock)) || Number(product.stock) < 1) return showToast("Bu məhsul hazırda stokda yoxdur."); const key = `${product.id}-${options.color || ""}-${options.size || ""}`; const found = state.cart.find(item => item.key === key); if (found && found.quantity >= product.stock) return showToast("Stokda olan maksimum say səbətindədir."); if (found) found.quantity += 1; else state.cart.push({ key, productId: product.id, quantity: 1, selectedColor: options.color || product.colors?.[0] || "", selectedSize: options.size || product.sizes?.[0] || "" }); writeStore("yerli_cart", state.cart); updateCartCount(); showToast(`${product.title} səbətə əlavə edildi`); }
function updateCartCount() { $("#cart-count").textContent = state.cart.reduce((total, item) => total + item.quantity, 0); }
function cartTotal() { return state.cart.reduce((total, item) => { const product = state.products.find(productItem => productItem.id === item.productId); return total + (product ? product.price * item.quantity : 0); }, 0); }
function renderCart() { const container = $("#cart-items"); if (!state.cart.length) { container.innerHTML = `<div class="cart-empty"><div class="cart-empty-icon">▱</div><h3>Səbətin hələ boşdur</h3><p>Bəyəndiyin məhsulları buraya əlavə et.</p></div>`; $("#cart-footer").innerHTML = ""; return; } container.innerHTML = state.cart.map(item => { const product = state.products.find(p => p.id === item.productId); if (!product) return ""; return `<div class="cart-item" data-cart-key="${escapeHtml(item.key)}"><img src="${escapeHtml(productImage(product))}" alt="${escapeHtml(product.title)}" /><div class="cart-item-info"><div class="cart-item-title">${escapeHtml(product.title)}</div><div class="cart-item-store">${escapeHtml(product.store)} · ${escapeHtml(item.selectedSize)}</div><div class="cart-item-bottom"><div class="qty-control"><button data-qty="minus">−</button><span>${item.quantity}</span><button data-qty="plus">＋</button></div><strong>${money(product.price * item.quantity)}</strong></div><button class="cart-remove" data-cart-remove>Sil</button></div></div>`; }).join(""); $("#cart-footer").innerHTML = `<div class="cart-total"><span>Məhsullar</span><span>${money(cartTotal())}</span></div><button class="checkout-btn" id="checkout-btn">Sifarişi rəsmiləşdir</button><p class="checkout-note">Sifariş serverdə qeydiyyata alınır. Çatdırılma ünvanı, kuryer haqqı və ödəniş üsulu checkout-da seçilir.</p>`; }
function showProductDetail(product) { const colors = (product.colors || []).map((color, index) => `<button class="variant-btn ${index === 0 ? "active" : ""}" data-variant="color">${escapeHtml(color)}</button>`).join(""); const sizes = (product.sizes || []).map((size, index) => `<button class="variant-btn ${index === 0 ? "active" : ""}" data-variant="size">${escapeHtml(size)}</button>`).join(""); const images = product.images?.length ? product.images.map(image => mediaUrl(image.ai_processed_url || image.original_url)) : [productImage(product)]; $("#product-detail").innerHTML = `<div class="product-detail-grid"><div class="detail-image"><img id="detail-main-image" src="${escapeHtml(images[0])}" alt="${escapeHtml(product.title)}" />${images.length > 1 ? `<div class="detail-thumbnails">${images.map((image, index) => `<button class="detail-thumb ${index === 0 ? "active" : ""}" data-detail-image="${escapeHtml(image)}"><img src="${escapeHtml(image)}" alt="${index + 1}-ci şəkil" /></button>`).join("")}</div>` : ""}</div><div class="detail-copy"><span class="eyebrow">${escapeHtml(product.category)}</span><h2>${escapeHtml(product.title)}</h2><div class="detail-store">${escapeHtml(product.store)} · ${escapeHtml(product.city)}</div><p class="detail-description">${escapeHtml(product.description || "Yerli mağazadan seçilmiş məhsul.")}</p><div class="detail-meta"><span class="meta-pill">${escapeHtml(product.material || "Material qeyd olunmayıb")}</span><span class="meta-pill">${product.stock > 0 ? `${product.stock} ədəd stokda` : "Mövcud deyil"}</span></div><div class="detail-price">${money(product.price)}</div>${colors ? `<div class="variant-row"><label>Rəng</label><div class="variant-options">${colors}</div></div>` : ""}${sizes ? `<div class="variant-row"><label>Ölçü</label><div class="variant-options">${sizes}</div></div>` : ""}<button class="add-detail-btn" id="add-detail-btn">Səbətə əlavə et</button></div></div>`; $$('[data-variant]').forEach(button => button.addEventListener("click", () => { $$(`[data-variant="${button.dataset.variant}"]`).forEach(item => item.classList.remove("active")); button.classList.add("active"); })); $$('[data-detail-image]').forEach(button => button.addEventListener("click", () => { $("#detail-main-image").src = button.dataset.detailImage; $$('[data-detail-image]').forEach(item => item.classList.toggle("active", item === button)); })); $("#add-detail-btn").addEventListener("click", () => { addToCart(product, { color: $("[data-variant=\"color\"].active")?.textContent, size: $("[data-variant=\"size\"].active")?.textContent }); closeAllLayers(); }); openModal("#product-modal"); }

function renderAuth() { const content = $("#auth-content"); if (authStep === 1) { content.innerHTML = `<span class="eyebrow">Təhlükəsiz giriş</span><h2>Yerli hesabına daxil ol.</h2><p>Email və ya telefon nömrənə birdəfəlik kod göndərəcəyik. Hesab və mağaza məlumatları serverdə saxlanılır.</p><form id="auth-request-form"><div class="form-field"><label for="auth-identifier">Email və ya telefon</label><input id="auth-identifier" required placeholder="sən@example.com və ya +994 50 000 00 00" value="${escapeHtml(authIdentifier)}" /></div><div class="form-error" id="auth-error"></div><button class="primary-wide" type="submit">Kod göndər <span>→</span></button></form>`; $("#auth-request-form").addEventListener("submit", requestOtpEnhanced); } else { content.innerHTML = `<span class="eyebrow">Təsdiq kodu</span><h2>Gələn kodu yaz.</h2><p><strong>${escapeHtml(authIdentifier)}</strong> üçün 6 rəqəmli kodu daxil et.</p><form id="auth-verify-form"><div class="form-field"><label for="auth-code">Birdəfəlik kod</label><input id="auth-code" required inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="123456" /></div><div class="form-error" id="auth-error"></div><button class="primary-wide" type="submit">Daxil ol <span>→</span></button></form><button class="secondary-btn auth-back" id="auth-back">Nömrəni/emaili dəyiş</button>`; $("#auth-verify-form").addEventListener("submit", verifyOtp); $("#auth-back").addEventListener("click", () => { authStep = 1; renderAuth(); }); } }
async function requestOtp(event) { event.preventDefault(); const identifier = $("#auth-identifier").value.trim(); const error = $("#auth-error"); error.classList.remove("show"); try { const result = await api("/api/auth/request-otp", { method: "POST", body: JSON.stringify({ identifier }) }); authIdentifier = identifier; authStep = 2; renderAuth(); if (result.devCode) showToast(`Demo kodu: ${result.devCode}`); else showToast(`Kod ${result.channel === "sms" ? "SMS" : "email"} ilə göndərildi`); } catch (err) { error.textContent = err.message; error.classList.add("show"); } }
async function verifyOtp(event) { event.preventDefault(); const error = $("#auth-error"); error.classList.remove("show"); try { const result = await api("/api/auth/verify-otp", { method: "POST", body: JSON.stringify({ identifier: authIdentifier, code: $("#auth-code").value.trim() }) }); sessionStorage.setItem("yerli_token", result.token); state.user = result.user; state.store = result.store || null; updateAuthButton(); closeAllLayers(); showToast("Hesabına daxil oldun"); const callback = afterAuth; afterAuth = null; callback?.(); } catch (err) { error.textContent = err.message; error.classList.add("show"); } }
function openAuth(callback = null) { afterAuth = callback; authStep = 1; authIdentifier = state.user?.identifier || ""; renderAuth(); openModal("#auth-modal"); }
function ensureAuth(callback) { if (state.user) callback(); else openAuth(callback); }

function renderSellerDashboard() { const container = $("#seller-dashboard"); if (!container || !state.store) return; const mine = state.products.filter(product => product.storeId === state.store.id || product.store === state.store.name); container.innerHTML = `<span class="eyebrow">Mağaza sahibinin səhifəsi</span><h2>${escapeHtml(state.store.name)}</h2><p>Alıcılar bu mağazanın məhsullarını, qiymətlərini və şəhərini kataloqda görür. Buradan vitrini idarə edə bilərsən.</p><div class="seller-profile-card"><span class="seller-profile-mark">${escapeHtml(state.store.name.split(/\s+/).map(part => part[0]).join("").slice(0, 2).toUpperCase())}</span><div><strong>${escapeHtml(state.store.name)}</strong><small>${escapeHtml(state.store.city)} · ${mine.length} məhsul</small><p>${escapeHtml(state.store.description || "Mağazan üçün qısa təsvir əlavə et.")}</p></div></div><div class="seller-dashboard-actions"><button class="primary-wide" id="dashboard-add-product">＋ Yeni məhsul əlavə et</button><button class="secondary-btn" id="dashboard-view-store">Alıcı kimi mağazama bax</button></div><div class="seller-products-head"><strong>Mənim məhsullarım</strong><span>${mine.length} məhsul</span></div><div class="seller-products-list">${mine.length ? mine.map(product => `<div class="seller-product-row"><img src="${escapeHtml(productImage(product))}" alt="${escapeHtml(product.title)}" /><div><strong>${escapeHtml(product.title)}</strong><small>${escapeHtml(product.category)} · ${money(product.price)}</small></div><span>${product.stock || 0} stok</span></div>`).join("") : `<div class="seller-empty">Hələ məhsul əlavə etməmisən.</div>`}</div>`; $("#dashboard-add-product").addEventListener("click", () => { closeAllLayers(); sellerStep = 2; sellerDraft = state.store || {}; renderSeller(); openModal("#seller-modal"); }); $("#dashboard-view-store").addEventListener("click", () => { closeAllLayers(); state.query = state.store.name; $("#search-input").value = state.store.name; renderProducts(); $("#catalog").scrollIntoView({ behavior: "smooth" }); }); }
function renderSeller() { const content = $("#seller-content"); $$(".seller-step").forEach((step, index) => step.classList.toggle("active", index + 1 === sellerStep)); if (sellerStep === 1) { content.innerHTML = `<span class="eyebrow">Serverdə mağaza profilin</span><h2>Mağazanı bir neçə addımda yarat.</h2><p>Profil məlumatların hesabına bağlı saxlanılır və bütün cihazlarda istifadə olunur.</p><form id="store-form"><div class="form-grid"><div class="form-field"><label for="store-name">Mağaza adı *</label><input id="store-name" required placeholder="məs. NOVA Studio" value="${escapeHtml(sellerDraft.name || "")}" /></div><div class="form-field"><label for="store-owner">Adın</label><input id="store-owner" placeholder="Ad və soyad" value="${escapeHtml(sellerDraft.owner || "")}" /></div><div class="form-field"><label for="store-location">Şəhər / rayon *</label><select id="store-location" required><option value="">Seç</option>${cities.map(city => `<option ${sellerDraft.city === city ? "selected" : ""}>${city}</option>`).join("")}</select></div><div class="form-field"><label for="store-contact">Əlaqə nömrəsi *</label><input id="store-contact" required placeholder="+994 50 000 00 00" value="${escapeHtml(sellerDraft.phone || state.user?.identifier || "")}" /></div><div class="form-field full"><label for="store-description">Qısa təsvir</label><textarea id="store-description" placeholder="Mağazanı bir cümlə ilə tanıt">${escapeHtml(sellerDraft.description || "")}</textarea></div></div><div class="form-error" id="store-error">Zəhmət olmasa, tələb olunan sahələri doldur.</div><button class="primary-wide" type="submit">Mağazanı yadda saxla və məhsul əlavə et <span>→</span></button></form>`; $("#store-form").addEventListener("submit", async event => { event.preventDefault(); const form = event.currentTarget; const error = $("#store-error"); if (!form.checkValidity()) { error.classList.add("show"); return; } try { const result = await api("/api/stores", { method: "POST", body: JSON.stringify({ name: $("#store-name").value.trim(), owner: $("#store-owner").value.trim(), city: $("#store-location").value, phone: $("#store-contact").value.trim(), description: $("#store-description").value.trim() }) }); state.store = result.store; state.stores = [...state.stores.filter(store => store.id !== result.store.id), result.store]; sellerDraft = result.store; updateAuthButton(); renderStores(); sellerStep = 2; renderSeller(); } catch (err) { error.textContent = err.message; error.classList.add("show"); } }); return; }
  if (sellerStep === 2) {
    const uploaded = sellerDraft.images || [];
    content.innerHTML = `<span class="eyebrow">Məhsul şəkilləri</span><h2>Şəkilləri əlavə et.</h2><p>Şəkillər olduğu kimi məhsula əlavə olunur. JPG, PNG və WEBP faylları qəbul edilir.</p><label class="upload-zone" id="upload-zone" for="product-image"><div><div class="upload-icon">↥</div><h3>Şəkli buraya at və ya seç</h3><p>1–8 şəkil · hər biri maksimum 10 MB</p><span class="upload-label">Şəkil seç</span><input id="product-image" type="file" accept="image/png,image/jpeg,image/webp" multiple /></div></label>${uploaded.length ? `<div class="ai-processing">${uploaded.map((image, index) => `<div class="image-preview"><img src="${escapeHtml(mediaUrl(image.originalUrl))}" alt="${index + 1}-ci məhsul şəkli" /><span class="preview-label">Şəkil ${index + 1}</span></div>`).join("")}</div><div class="ai-actions"><button class="secondary-btn" id="change-images">Şəkilləri dəyiş</button><button class="primary-wide" id="continue-product" style="margin:0">Məhsul məlumatları <span>→</span></button></div>` : ""}`;
    const selectImages = files => { if (files.length) readProductImages(files); };
    $("#product-image")?.addEventListener("change", event => selectImages([...event.target.files || []]));
    const zone = $("#upload-zone");
    if (zone) { ["dragenter", "dragover"].forEach(type => zone.addEventListener(type, event => { event.preventDefault(); zone.classList.add("dragging"); })); ["dragleave", "drop"].forEach(type => zone.addEventListener(type, event => { event.preventDefault(); zone.classList.remove("dragging"); })); zone.addEventListener("drop", event => { event.preventDefault(); selectImages([...event.dataTransfer.files || []]); }); }
    $("#change-images")?.addEventListener("click", () => { sellerDraft.images = []; renderSeller(); });
    $("#continue-product")?.addEventListener("click", () => { sellerStep = 3; renderSeller(); });
    return;
  }
  content.innerHTML = `<span class="eyebrow">Son addım</span><h2>Məhsul məlumatlarını tamamla.</h2><p>Məhsulun alıcı kataloqunda mağaza adın və qiymətinlə görünəcək.</p><form id="product-form"><div class="form-grid"><div class="form-field full"><label for="product-title">Başlıq *</label><input id="product-title" required placeholder="məs. Kişi köynəyi" /></div><div class="form-field"><label for="product-category">Kateqoriya *</label><select id="product-category" required><option value="">Seç</option><option>Geyim</option><option>Ayaqqabı</option><option>Çanta</option><option>Aksesuar</option><option>Ev & həyat</option><option>Gözəllik</option></select></div><div class="form-field"><label for="product-subtype">Növ / model</label><input id="product-subtype" placeholder="məs. İdman ayaqqabısı" /></div><div class="form-field"><label for="product-color">Rənglər</label><input id="product-color" placeholder="Qara, ağ" /></div><div class="form-field"><label for="product-size">Ölçülər</label><input id="product-size" placeholder="S, M, L və ya 38, 39" /></div><div class="form-field"><label for="product-material">Material</label><input id="product-material" placeholder="Pambıq, dəri..." /></div><div class="form-field"><label for="product-price">Qiymət (AZN) *</label><input id="product-price" required min="1" step="0.01" type="number" placeholder="0" /></div><div class="form-field"><label for="product-stock">Stok</label><input id="product-stock" min="0" type="number" placeholder="Məs. 10" /></div></div><div class="form-error" id="product-error">Başlıq, kateqoriya və düzgün qiymət daxil et.</div><button class="primary-wide" type="submit">Məhsulu alıcı kataloquna yayımla <span>↗</span></button></form>`; $("#product-form").addEventListener("submit", async event => { event.preventDefault(); const form = event.currentTarget; const price = Number($("#product-price").value); const error = $("#product-error"); if (!form.checkValidity() || price <= 0) { error.classList.add("show"); return; } try { const response = await api("/api/products", { method: "POST", body: JSON.stringify({ title: $("#product-title").value.trim(), category: $("#product-category").value, subtype: $("#product-subtype").value.trim(), material: $("#product-material").value.trim(), colors: $("#product-color").value.split(",").map(item => item.trim()).filter(Boolean), sizes: $("#product-size").value.split(",").map(item => item.trim()).filter(Boolean), price, stock: Number($("#product-stock").value || 0), images: sellerDraft.images || [{ originalUrl: sellerDraft.originalUrl, processedUrl: sellerDraft.processedUrl }] }) }); state.products.push(response.product); sellerStep = 1; sellerDraft = state.store || {}; closeAllLayers(); renderProducts(); renderStores(); showToast("Məhsul yoxlanış üçün göndərildi"); } catch (err) { error.textContent = err.message; error.classList.add("show"); } }); }
function readProductImage(file) { readProductImages([file]); }
async function readProductImages(files) {
  if (!files.length || files.length > 8) return showToast("Bir məhsul üçün 1–8 şəkil seç.");
  if (files.some(file => !["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 10 * 1024 * 1024)) return showToast("Yalnız 10 MB-dan kiçik JPG, PNG və WEBP şəkillər seç.");
  try {
    const images = [];
    for (const file of files) {
      const dataUrl = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = event => resolve(event.target.result); reader.onerror = reject; reader.readAsDataURL(file); });
      const result = await api("/api/media/process", { method: "POST", body: JSON.stringify({ dataUrl, fileName: file.name }) });
      images.push({ originalUrl: result.originalUrl, processedUrl: result.originalUrl });
    }
    sellerDraft.images = images;
    renderSeller();
  } catch (error) { showToast(error.message || "Şəkil yüklənmədi."); }
}

function renderCheckout() { const content = $("#checkout-content"); content.innerHTML = `<span class="eyebrow">Server sifarişi</span><h2>Sifarişi rəsmiləşdir.</h2><p>Çatdırılma məlumatlarını daxil et; sifariş mağazaya və serverə qeyd olunacaq.</p><form id="checkout-form"><div class="form-grid"><div class="form-field"><label for="checkout-name">Ad, soyad *</label><input id="checkout-name" required /></div><div class="form-field"><label for="checkout-phone">Telefon *</label><input id="checkout-phone" required placeholder="+994 50 000 00 00" value="${escapeHtml(state.user?.identifierType === "sms" ? state.user.identifier : "")}" /></div><div class="form-field"><label for="checkout-city">Şəhər / rayon *</label><select id="checkout-city" required>${cities.map(city => `<option>${city}</option>`).join("")}</select></div><div class="form-field"><label for="checkout-payment">Ödəniş üsulu *</label><select id="checkout-payment"><option value="cash">Qapıda nağd</option></select></div><div class="form-field full"><label for="checkout-address">Ünvan *</label><input id="checkout-address" required placeholder="Küçə, bina, mənzil" /></div><div class="form-field full"><label for="checkout-note">Qeyd</label><textarea id="checkout-note" placeholder="Kuryer üçün əlavə qeyd"></textarea></div></div><div class="checkout-summary"><span>Səbət</span><strong>${money(cartTotal())}</strong></div><div class="form-error" id="checkout-error"></div><button class="primary-wide" type="submit">Sifarişi serverə göndər <span>→</span></button></form>`; $("#checkout-form").addEventListener("submit", submitOrder); }
async function submitOrder(event) { event.preventDefault(); const error = $("#checkout-error"); error.classList.remove("show"); const button = event.currentTarget.querySelector('button[type="submit"]'); const body = { items: state.cart, customer: { name: $("#checkout-name").value.trim(), phone: $("#checkout-phone").value.trim(), note: $("#checkout-note").value.trim() }, shipping: { city: $("#checkout-city").value, address: $("#checkout-address").value.trim() }, payment: { method: $("#checkout-payment").value } }; const key = crypto.randomUUID(); try { button.disabled = true; const quote = await api("/api/orders/quote", { method: "POST", body: JSON.stringify(body) }); $(".checkout-summary").innerHTML = `<span>Məhsullar və çatdırılma</span><strong>${money(quote.quote.total)}</strong>`; const response = await api("/api/orders", { method: "POST", headers: { "Idempotency-Key": key }, body: JSON.stringify(body) }); const checkoutUrl = response.order?.payment?.checkoutUrl; if (checkoutUrl) { window.location.href = checkoutUrl; return; } state.cart = []; writeStore("yerli_cart", state.cart); updateCartCount(); closeAllLayers(); showToast(`Sifariş qəbul edildi: ${response.order.id}`); } catch (err) { error.textContent = err.message; error.classList.add("show"); button.disabled = false; } }
function openCheckout() { ensureAuth(() => { renderCheckout(); openModal("#checkout-modal"); }); }

async function loadSession() { const token = sessionStorage.getItem("yerli_token"); if (!token) return; try { const result = await api("/api/auth/me"); state.user = result.user; state.store = result.store; updateAuthButton(); } catch { sessionStorage.removeItem("yerli_token"); } }
async function loadProducts() { try { const result = await api("/api/products"); if (Array.isArray(result.products) && result.products.length) state.products = result.products; state.stores = result.stores || []; } catch { showToast("Kataloq demo məlumatı ilə açıldı; serveri işə salanda canlı data yüklənəcək."); } renderProducts(); renderStores(); }

function bindEvents() {
  $("#search-submit").addEventListener("click", () => { state.query = $("#search-input").value.trim(); renderProducts(); $("#catalog").scrollIntoView({ behavior: "smooth" }); }); $("#search-input").addEventListener("keydown", event => { if (event.key === "Enter") $("#search-submit").click(); }); $$(".popular-searches button").forEach(button => button.addEventListener("click", () => { $("#search-input").value = button.dataset.query; $("#search-submit").click(); }));
  $$(".cat-pill").forEach(button => button.addEventListener("click", () => { state.category = button.dataset.category; setCategoryPills(); renderProducts(); })); [["#location-filter", "location"], ["#type-filter", "type"], ["#color-filter", "color"], ["#size-filter", "size"], ["#sort-select", "sort"]].forEach(([selector, key]) => $(selector).addEventListener("change", event => { state[key] = event.target.value; renderProducts(); })); ["#min-price", "#max-price"].forEach(selector => $(selector).addEventListener("input", event => { state[selector === "#min-price" ? "minPrice" : "maxPrice"] = event.target.value; renderProducts(); })); $("#clear-filters").addEventListener("click", clearFilters); $("#empty-reset").addEventListener("click", clearFilters); $("#open-filters").addEventListener("click", () => $("#filters-panel").classList.add("open")); $("#close-filters").addEventListener("click", () => $("#filters-panel").classList.remove("open")); $("#open-cart").addEventListener("click", openCart); $("#open-search").addEventListener("click", () => { $("#search-input").focus(); $("#search-input").scrollIntoView({ behavior: "smooth", block: "center" }); });
  $("#open-auth").addEventListener("click", () => { if (!state.user) return openAuth(); if (state.user.role === "admin") return renderAdmin(); if (state.store) return renderSellerDashboardEnhanced(); showToast(`Daxil olmusan: ${state.user.identifier}`); }); const openSeller = () => ensureAuth(() => { if (state.user?.role === "admin") return renderAdmin(); if (state.store) return renderSellerDashboardEnhanced(); sellerStep = 1; sellerDraft = {}; renderSeller(); openModal("#seller-modal"); }); $("#open-seller").addEventListener("click", openSeller); $("#browse-stores").addEventListener("click", () => $("#stores").scrollIntoView({ behavior: "smooth", block: "start" })); $("#open-mobile-menu").addEventListener("click", () => showToast("Məhsullar · Mağazalar · Səbət")); $$("[data-legal]").forEach(button => button.addEventListener("click", () => renderLegal(button.dataset.legal)));
  $("#stores-grid").addEventListener("click", event => { const card = event.target.closest("[data-store-name]"); if (!card) return; state.query = card.dataset.storeName; $("#search-input").value = state.query; renderProducts(); $("#catalog").scrollIntoView({ behavior: "smooth" }); });
  productsGrid.addEventListener("click", event => { const add = event.target.closest("[data-add]"); if (add) { event.stopPropagation(); const product = state.products.find(item => item.id === add.dataset.add); if (product) addToCart(product); return; } const favorite = event.target.closest("[data-favorite]"); if (favorite) { event.stopPropagation(); toggleFavorite(favorite.dataset.favorite); return; } const card = event.target.closest("[data-product-id]"); if (card) { const product = state.products.find(item => item.id === card.dataset.productId); if (product) showProductDetail(product); } }); productsGrid.addEventListener("keydown", event => { if (event.key === "Enter") event.target.closest("[data-product-id]")?.click(); }); $("#active-filters").addEventListener("click", event => { const button = event.target.closest("[data-remove-filter]"); if (button) { $("#active-filters")._filterActions?.[Number(button.dataset.removeFilter)](); renderProducts(); } });
  $("#cart-items").addEventListener("click", event => { const itemEl = event.target.closest("[data-cart-key]"); if (!itemEl) return; const item = state.cart.find(entry => entry.key === itemEl.dataset.cartKey); if (!item) return; if (event.target.closest("[data-cart-remove]")) state.cart = state.cart.filter(entry => entry.key !== item.key); if (event.target.closest("[data-qty=plus]")) item.quantity += 1; if (event.target.closest("[data-qty=minus]")) item.quantity = Math.max(0, item.quantity - 1); state.cart = state.cart.filter(entry => entry.quantity > 0); writeStore("yerli_cart", state.cart); updateCartCount(); renderCart(); }); $("#cart-footer").addEventListener("click", event => { if (event.target.id === "checkout-btn") openCheckout(); }); modalBackdrop.addEventListener("click", closeAllLayers); $$('[data-close-modal], [data-close-drawer]').forEach(button => button.addEventListener("click", closeAllLayers)); document.addEventListener("keydown", event => { if (event.key === "Escape") closeAllLayers(); });
}

async function boot() { updateCartCount(); updateAuthButton(); bindEvents(); await loadSession(); await loadProducts(); const params = new URLSearchParams(location.search); if (params.get("status") === "success") showToast("Kart ödənişi tamamlandı"); }
boot();

function statusLabel(status) { return ({ active: "Təsdiqlənib", pending: "Yoxlanılır", rejected: "Rədd edilib", new: "Yeni", awaiting_payment: "Ödəniş gözlənilir", cancelled: "Ləğv edilib" })[status] || status || "—"; }
function statusPill(status) { return `<span class="status-pill ${escapeHtml(status || "")}">${escapeHtml(statusLabel(status))}</span>`; }
function renderSellerDashboardEnhanced() {
  const container = $("#seller-dashboard"); if (!container || !state.store) return; container.innerHTML = `<span class="eyebrow">Mağaza kabineti</span><h2>${escapeHtml(state.store.name)}</h2><p>${statusPill(state.store.status)} Məhsulları, stok və satışlarını buradan idarə et.</p><div class="seller-metrics" id="seller-metrics"><div><b>—</b><small>Sifariş</small></div><div><b>—</b><small>Satılan ədəd</small></div><div><b>—</b><small>Satış</small></div></div><div class="seller-products-head"><strong>Məhsullar</strong><span id="seller-product-count">Yüklənir…</span></div><div class="seller-products-list" id="seller-product-list"></div><div class="seller-products-head"><strong>Son sifarişlər</strong></div><div id="seller-order-list"></div><div class="seller-dashboard-actions"><button class="primary-wide" id="dashboard-add-product">＋ Yeni məhsul</button><button class="secondary-btn" id="dashboard-view-store">Vitrinə bax</button></div>`; openModal("#seller-dashboard-modal");
  $("#dashboard-add-product").addEventListener("click", () => { closeAllLayers(); sellerStep = 2; sellerDraft = state.store || {}; renderSeller(); openModal("#seller-modal"); }); $("#dashboard-view-store").addEventListener("click", () => { closeAllLayers(); state.query = state.store.name; $("#search-input").value = state.store.name; renderProducts(); $("#catalog").scrollIntoView({ behavior: "smooth" }); });
  Promise.all([api("/api/seller/products"), api("/api/seller/orders")]).then(([productResult, orderResult]) => { const products = productResult.products || []; $("#seller-product-count").textContent = `${products.length} məhsul`; $("#seller-metrics").innerHTML = `<div><b>${orderResult.sales.orders}</b><small>Sifariş</small></div><div><b>${orderResult.sales.units}</b><small>Satılan ədəd</small></div><div><b>${money(orderResult.sales.revenue)}</b><small>Satış</small></div>`; $("#seller-product-list").innerHTML = products.length ? products.map(product => `<form class="seller-product-editor" data-product-edit="${escapeHtml(product.id)}"><div><strong>${escapeHtml(product.title)}</strong><small>${statusPill(product.status)}</small></div><input name="price" type="number" min="0.01" step="0.01" aria-label="Qiymət" value="${Number(product.price)}"><input name="stock" type="number" min="0" step="1" aria-label="Stok" value="${Number(product.stock)}"><button type="submit">Yadda saxla</button></form>`).join("") : `<div class="seller-empty">Hələ məhsul yoxdur.</div>`; $("#seller-order-list").innerHTML = orderResult.orders.length ? orderResult.orders.slice(0, 8).map(order => `<div class="seller-order"><strong>${escapeHtml(order.title)} × ${order.quantity} · ${money(order.total)}</strong> ${statusPill(order.status)}<small>${escapeHtml(order.shipping.city)} · ${escapeHtml(order.shipping.address)} · ${escapeHtml(order.customer.name)}</small></div>`).join("") : `<div class="seller-empty">Hələ sifariş yoxdur.</div>`; $$("[data-product-edit]", container).forEach(form => form.addEventListener("submit", async event => { event.preventDefault(); const button = form.querySelector("button"); const price = Number(form.price.value), stock = Number(form.stock.value); if (!(price > 0) || !Number.isInteger(stock) || stock < 0) return showToast("Qiymət müsbət, stok isə sıfır və ya böyük tam ədəd olmalıdır."); button.disabled = true; try { await api(`/api/seller/products/${form.dataset.productEdit}`, { method: "PATCH", body: JSON.stringify({ price, stock }) }); showToast("Məhsul yeniləndi"); renderSellerDashboardEnhanced(); } catch (error) { showToast(error.message); button.disabled = false; } })); }).catch(error => { $("#seller-product-list").innerHTML = `<div class="seller-empty">${escapeHtml(error.message)}</div>`; });
}
async function renderAdmin() { const content = $("#admin-content"); content.innerHTML = `<span class="eyebrow">Admin paneli</span><h2>Moderasiya</h2><p>Gözləyən mağaza və məhsulları təsdiqlə və ya rədd et.</p><div id="admin-queue">Yüklənir…</div>`; openModal("#admin-modal"); try { const result = await api("/api/admin/pending"); const stores = result.stores || [], products = result.products || []; $("#admin-queue").innerHTML = `<h3>Mağazalar (${stores.length})</h3>${stores.map(store => `<div class="admin-row"><strong>${escapeHtml(store.name)} ${statusPill(store.status)}</strong><small>${escapeHtml(store.city)} · ${escapeHtml(store.phone)}</small><div class="admin-actions"><button data-admin-store="${escapeHtml(store.id)}" data-status="active">Təsdiqlə</button><button data-admin-store="${escapeHtml(store.id)}" data-status="rejected">Rədd et</button></div></div>`).join("") || `<p>Gözləyən mağaza yoxdur.</p>`}<h3>Məhsullar (${products.length})</h3>${products.map(product => `<div class="admin-row"><strong>${escapeHtml(product.title)} ${statusPill(product.status)}</strong><small>${escapeHtml(product.store)} · ${money(product.price)} · ${product.stock} stok</small><div class="admin-actions"><button data-admin-product="${escapeHtml(product.id)}" data-status="active">Təsdiqlə</button><button data-admin-product="${escapeHtml(product.id)}" data-status="rejected">Rədd et</button></div></div>`).join("") || `<p>Gözləyən məhsul yoxdur.</p>`}`; $$("[data-admin-store], [data-admin-product]", content).forEach(button => button.addEventListener("click", async () => { button.disabled = true; const resource = button.dataset.adminStore ? "stores" : "products"; const id = button.dataset.adminStore || button.dataset.adminProduct; try { await api(`/api/admin/${resource}/${id}`, { method: "PATCH", body: JSON.stringify({ status: button.dataset.status }) }); showToast("Status yeniləndi"); renderAdmin(); } catch (error) { showToast(error.message); button.disabled = false; } })); } catch (error) { $("#admin-queue").textContent = error.message; } }
function renderLegal(type) { const copy = { privacy: ["Məxfilik siyasəti", "Yerli yalnız sifarişi icra etmək, hesabı qorumaq və xidməti yaxşılaşdırmaq üçün ad, əlaqə və ünvan məlumatını emal edir. Ödəniş kartı məlumatı bu versiyada qəbul edilmir. Məlumatın silinməsi üçün dəstəyə müraciət et."], terms: ["İstifadə şərtləri", "Satıcı məhsul məlumatı, qiymət və stokun düzgünlüyünə cavabdehdir. Məhsullar moderasiyadan sonra görünür. Alıcı sifarişi göndərməzdən əvvəl məlumatları yoxlamalıdır. Qanuna və platforma qaydalarına zidd məhsullar dərc edilmir."], delivery: ["Çatdırılma və qaytarma", "Çatdırılma ünvan və mağaza sayına görə checkout-da hesablanır. Hazırda sifariş qapıda nağd ödənişlə qeydə alınır. Qaytarma şərtləri mağaza ilə razılaşdırılır; qüsurlu və ya səhv məhsul hallarında sifariş nömrəsi ilə dəstəyə müraciət et."] }[type] || ["Məlumat", "Məlumat tapılmadı."]; $("#legal-content").innerHTML = `<span class="eyebrow">Yerli</span><h2>${copy[0]}</h2><p>${copy[1]}</p>`; openModal("#legal-modal"); }
async function requestOtpEnhanced(event) { event.preventDefault(); const button = event.currentTarget.querySelector('button[type="submit"]'); const identifier = $("#auth-identifier").value.trim(); const error = $("#auth-error"); error.classList.remove("show"); button.disabled = true; try { const result = await api("/api/auth/request-otp", { method: "POST", body: JSON.stringify({ identifier }) }); authIdentifier = identifier; authStep = 2; renderAuth(); if (result.devCode) showToast(`Demo kodu: ${result.devCode}`); else showToast(`Kod ${result.channel === "sms" ? "SMS" : "email"} ilə göndərildi`); } catch (err) { error.textContent = err.message; error.classList.add("show"); button.disabled = false; } }


